   "newText": "def transform(grid):
    """Trace the colored glyphs as horizontal/vertical moves from marker 5.

    Glyphs are consumed top-to-bottom in the left stack, then top-to-bottom
    in the right stack. The marker's column is the current lane. A's 3-cell
    stroke moves right by two; B's 2-cell stroke moves left by one; D's
    4-cell stroke moves left by three; C draws two vertical cells without
    changing lane.
    """
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]
    mark = next(((r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5), (0, 8))
    lane = max(0, min(6, mark[1] - 8))
    out[mark[0]][lane] = 5

    tokens = []
    for c0 in (0, 4):
        for r0 in range(0, h - 2, 4):
            patch = [grid[r0 + dr][c0:c0 + 3] for dr in range(3)]
            color = next((v for row in patch for v in row if v not in (0, 4, 5)), 0)
            if not color:
                continue
            binary = tuple(tuple(1 if v == color else 0 for v in row) for row in patch)
            motif = _MOTIFS.get(binary)
            if motif:
                tokens.append((color, motif[0], motif[1]))

    y = mark[0] + 1
    for color, orient, length in tokens:
        if orient == "v":
            for _ in range(length):
                if y < h and 0 <= lane < 7:
                    out[y][lane] = color
                y += 1
        elif orient == "h":
            if length == 3:       # A: stroke starts at lane, then travels right.
                xs = range(lane, lane + length)
                lane += length - 1
            elif length == 2:     # B: stroke ends at lane, travels left.
                xs = range(lane - length + 1, lane + 1)
                lane -= length - 1
            else:                 # D: four-cell stroke ends at lane.
                xs = range(lane - length + 1, lane + 1)
                lane -= length - 1
            if y < h:
                for x in xs:
                    if 0 <= x < 7:
                        out[y][x] = color
            y += 1
    return out
